const dados = $input.all();

// Extrai valores de consumo
const consumos = dados.map(item => Number(item.json.media_consumo_kwh));

// Ordena para o cálculo dos quartis
consumos.sort((a, b) => a - b);

// Calcula quartis
const q1Index = Math.floor(consumos.length * 0.25);
const q3Index = Math.floor(consumos.length * 0.75);
const q1 = Number(consumos[q1Index]);
const q3 = Number(consumos[q3Index]);
const iqr = q3 - q1;

const limiteInferior = q1 - (1.5 * iqr);
const limiteSuperior = q3 + (1.5 * iqr);

// Calcula estatísticas
const mediaGeral = Math.round((consumos.reduce((sum, val) => sum + val, 0) / consumos.length) * 100) / 100;
const mediana = consumos[Math.floor(consumos.length / 2)];
const maxConsumo = Math.max(...consumos);
const minConsumo = Math.min(...consumos);

const resultados = [];
let totalClientes = 0;
let totalOutliers = 0;
let outliersAltoConsumo = 0;
let outliersBaixoConsumo = 0;

// Processa cada cliente
for (const item of dados) {
  const consumo = Number(item.json.media_consumo_kwh);
  let status = 'normal';
  let tipoOutlier = null;

  // Verificar se é outlier
  if (consumo < limiteInferior) {
    status = 'outlier';
    tipoOutlier = 'consumo_baixo';
    totalOutliers++;
    outliersBaixoConsumo++;
  } else if (consumo > limiteSuperior) {
    status = 'outlier';
    tipoOutlier = 'consumo_alto';
    totalOutliers++;
    outliersAltoConsumo++;
  }

  resultados.push({
    json: {
      ...item.json,
      status: status,
      tipo_outlier: tipoOutlier,
      percentual_acima_media: Math.round(((consumo - mediaGeral) / mediaGeral * 100) * 100) / 100
    }
  });

  totalClientes++;
}

const resultado = {
  json: {
    dados: resultados,
    estatisticas: {
      total_clientes: totalClientes,
      total_outliers: totalOutliers,
      outliers_alto_consumo: outliersAltoConsumo,
      outliers_baixo_consumo: outliersBaixoConsumo,
      percentual_outliers: Math.round((totalOutliers / totalClientes * 100) * 100) / 100,
      media_geral: mediaGeral,
      mediana: mediana,
      max_consumo: maxConsumo,
      min_consumo: minConsumo,
      q1: q1,
      q3: q3,
      iqr: Math.round(iqr * 100)/100,
      limite_inferior: Math.round(limiteInferior * 100)/100,
      limite_superior: Math.round(limiteSuperior * 100)/100,
      metodo_utilizado: 'Intervalo Interquartil (IQR) com fator 1.5'
    }
  }
};

return resultado;

const item = $input.item.json;

const estatisticas = item.estatisticas;

const outliers = item.dados.filter(item => item.json.status === 'outlier');

// Criar tabela formatada para outliers
let tabelaOutliers = '\
Tabela de Outliers Detalhados:\
| Cliente | Consumo Médio | Tipo | Desvio da Média |\
|---|---|---|---|\
';

outliers.forEach(o => {
  tabelaOutliers += `| ${o.json.nome} | ${o.json.media_consumo_kwh} kWh | ${o.json.tipo_outlier} | ${o.json.percentual_acima_media}% |\
`;
});

// Criar prompt com todos os dados
const promptCompleto = `ANÁLISE DE CONSUMO CONTRATOS ATIVOS - ÚLTIMOS 3 MESES

ESTATÍSTICAS GERAIS:
- Total de clientes com contratos ativos: ${estatisticas.total_clientes}
- Período analisado: últimos 3 meses
- Média: ${estatisticas.media_geral} kWh
- Mediana: ${estatisticas.mediana} kWh
- Maior consumo: ${estatisticas.max_consumo} kWh
- Menor consumo: ${estatisticas.min_consumo} kWh

IDENTIFICAÇÃO DE OUTLIERS (Método IQR):
- Total de outliers: ${estatisticas.total_outliers} (${estatisticas.percentual_outliers}%)
- Outliers de alto consumo: ${estatisticas.outliers_alto_consumo} clientes
- Outliers de baixo consumo: ${estatisticas.outliers_baixo_consumo} clientes
- Limite inferior (abaixo é outlier): ${estatisticas.limite_inferior} kWh
- Limite superior (acima é outlier): ${estatisticas.limite_superior} kWh

${tabelaOutliers}

- Total de outliers detalhados: ${outliers.length}

METODOLOGIA:
${estatisticas.metodo_utilizado}

POR FAVOR, ANALISE OS OUTLIERS LISTADOS NA TABELA ACIMA E FORNEÇA:
1. RESUMO
2. ANÁLISE
3. SUGESTÕES

Baseie sua análise nos dados completos fornecidos, especialmente na tabela de outliers.`;

return {
  json: {
    prompt_completo: promptCompleto
  }
};

